syntax:
std::istream& ignore (std::streamsize n = 1, int_type delim = traits::eof());

//Implementation notes:
//1.  The implementation utilizes the stream buffer's internal `sbumpc()` or `sgetn()` methods for character extraction. 
//2.  If `n` is large, it likely performs multiple system calls to read from the file/input stream. 
//3.  Finding the delimiter early significantly reduces the number of characters processed and improves performance. 
//4. Optimizations vary across compiler implementations, potentially using SIMD or other techniques to accelerate bulk character discarding.

code_example:
#include <iostream>
#include <limits>
#include <fstream>
int main() {
  std::ifstream file("large_file.txt");
  if (file.is_open()) {
    // Ignore the first 1024 characters
    file.ignore(1024); 
    // Ignore characters until a newline is encountered
    file.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
    //Process the rest of the file...
    file.close();
  }
  return 0;
}
